The method is used to get the textAnchor of title / subTitle.

Specifies the text alignment of title.
/// Specifies the chart render in RTL mode.

example.code:

// This example demonstrates how to bind the datasource in chart series.
<SfChart>
    <ChartSeriesCollection>
        <ChartSeries DataSource="@Data" XName="XValue" YName="YValue" />
    </ChartSeriesCollection>
</SfChart>
@code {
    public class ChartData
    {
        public double XValue { get; set; }
        public double YValue { get; set; }
    }

    public List<ChartData> Data = new List<ChartData>
    {
        new ChartData { XValue = 10, YValue = 21 },
        new ChartData { XValue = 20, YValue = 24 },
        new ChartData { XValue = 30, YValue = 36 }
    };
}


// This example demonstrates how to bind remote data using SfDataManager in a Syncfusion Blazor Chart.
<SfChart>
    <SfDataManager Url="https://services.odata.org/V4/Northwind/Northwind.svc/Orders" Adaptor="Syncfusion.Blazor.Adaptors.ODataV4Adaptor">
    </SfDataManager>
    <ChartPrimaryXAxis ValueType="Syncfusion.Blazor.Charts.ValueType.Category" RangePadding="ChartRangePadding.Additional"/>
    <ChartSeriesCollection>
        <ChartSeries Query="ChartQuery" XName="OrderID" YName="Freight" Type="ChartSeriesType.Column"></ChartSeries>
    </ChartSeriesCollection>
</SfChart>
@code {
    public Query ChartQuery { get; set; }

    protected override void OnInitialized()
    {
        ChartQuery = new Query().Take(10).Where("Freight", "GreaterThan", 300, false);
    }

}


// This example demonstrates how to use PointColorMapping in a column chart to apply different colors to each data point.
<SfChart>
    <ChartSeriesCollection>
        <ChartSeries DataSource="@Data" XName="XValue" YName="YValue" Type="ChartSeriesType.Column" PointColorMapping="Color"/>
    </ChartSeriesCollection>
</SfChart>
@code {
    public class ChartData
    {
        public double XValue { get; set; }
        public double YValue { get; set; }
        public string Color { get; set; }
    }

    public List<ChartData> Data = new List<ChartData>
    {
        new ChartData { XValue = 10, YValue = 21 , Color = "red"},
        new ChartData { XValue = 20, YValue = 24 , Color = "green"},
        new ChartData { XValue = 30, YValue = 36 , Color = "blue"}
    };
}


// This example demonstrates how to render a bubble chart using Size property.
<SfChart>
    <ChartSeriesCollection>
        <ChartSeries DataSource="@Data" XName="XValue" YName="YValue" Type="ChartSeriesType.Bubble" Size="BubbleSize"/>
    </ChartSeriesCollection>
</SfChart>
@code {
    public class ChartData
    {
        public double XValue { get; set; }
        public double YValue { get; set; }
        public double BubbleSize { get; set; }
    }

    public List<ChartData> Data = new List<ChartData>
    {
        new ChartData { XValue = 10, YValue = 21 , BubbleSize = 1.241},
        new ChartData { XValue = 20, YValue = 24 , BubbleSize = 3.234},
        new ChartData { XValue = 30, YValue = 36 , BubbleSize = 5.634}
    };
}


// This example demonstrates how to apply a custom style to selected chart points.
<style>
.selection {
    fill: yellow;
}
</style>
<SfChart SelectionMode="SelectionMode.Point">
    <ChartSeriesCollection>
        <ChartSeries DataSource="@Data" XName="XValue" YName="YValue" 
                     Type="ChartSeriesType.Column" SelectionStyle="selection" />
    </ChartSeriesCollection>
</SfChart>


// This example demonstrates how to apply a custom style to unselected chart points.
<style>
.selection {
    fill: yellow;
}
.unselection {
    fill: blue;
}
</style>
<SfChart SelectionMode="SelectionMode.Point">
    <ChartSeriesCollection>
        <ChartSeries DataSource="@Data" XName="XValue" YName="YValue" 
                     Type="ChartSeriesType.Column" SelectionStyle="selection" UnSelectedStyle="unselection" />
    </ChartSeriesCollection>
</SfChart>


// This example demonstrates how to apply a custom style to unhighlighted chart points.
<style>
.selection {
    fill: yellow;
}
.unselection {
    fill: blue;
}
</style>
<SfChart SelectionMode="SelectionMode.Point">
    <ChartSeriesCollection>
        <ChartSeries DataSource="@Data" XName="XValue" YName="YValue" 
                     Type="ChartSeriesType.Column" HighlightStyle="selection" NonHighlightStyle="unselection" />
    </ChartSeriesCollection>
</SfChart>


// This example demonstrates how to apply a custom style to highlight chart points.
<style>
.selection {
    fill: yellow;
}
</style>
<SfChart SelectionMode="SelectionMode.Point">
    <ChartSeriesCollection>
        <ChartSeries DataSource="@Data" XName="XValue" YName="YValue" 
                     Type="ChartSeriesType.Column" HighlightStyle="selection" />
    </ChartSeriesCollection>
</SfChart>


// The following code demonstrates how to use the Name property to set a data label field name:
<SfChart>
    <ChartSeriesCollection>
        <ChartSeries DataSource="@WeatherReports" XName="X" YName="Y">
            <ChartMarker>
                <ChartDataLabel Visible="true" Name="Text" />
            </ChartMarker>
        </ChartSeries>
    </ChartSeriesCollection>
</SfChart>
@code {
public class ChartData
{
    public double X { get; set; }
    public double Y { get; set; }
    public string Text { get; set; }
}
public List<ChartData> WeatherReports = new List<ChartData>
{
    new ChartData { X = 10, Y = 21, Text = "X:10 and Y:21" },
    new ChartData { X = 20, Y = 24, Text = "X:20 and Y:24" },
    new ChartData { X = 30, Y = 36, Text = "X:30 and Y:36" },
    new ChartData { X = 40, Y = 38, Text = "X:40 and Y:38" }
};
}


// The following example demonstrates how to set the empty point mode to <c>Average</c>:
<SfChart>
    <ChartSeriesCollection>
        <ChartSeries DataSource="@WeatherReports" XName="X" YName="Y" Type="ChartSeriesType.Column">
            <ChartEmptyPointSettings Mode="EmptyPointMode.Average" />
        </ChartSeries>
    </ChartSeriesCollection>
</SfChart>
@code {
public class ChartData
{
    public double X { get; set; }
    public double? Y { get; set; }
}
public List<ChartData> WeatherReports = new List<ChartData>
{
    new ChartData { X = 10, Y = 21 },
    new ChartData { X = 20, Y = null },
    new ChartData { X = 30, Y = 36 },
    new ChartData { X = 40, Y = 38 }
};
}

members.member:
Gets or sets the URL path for the image.
A string representing the URL of the image to be used as the marker.
Specifying the URL allows for the use of custom images as markers, enhancing the visual representation of data points on the chart.
///
// This example demonstrates how to display an image as a marker in a chart series. <SfChart> <ChartSeriesCollection> <ChartSeries DataSource="@Data" Name="England" XName="XValue" YName="YValue"> <ChartMarker Visible="true" Shape="ChartShape.Image" ImageUrl="https://ej2.syncfusion.com/demos/src/chart/images/cloud.png" Height="30" Width="30"/> </ChartSeries> </ChartSeriesCollection> </SfChart>

example.code:

// This example demonstrates how to set the height of a Syncfusion Blazor Chart.
<SfChart Height="400px">
</SfChart>


// This example demonstrates how to set the Width of a Syncfusion Blazor Chart.
<SfChart Width="400px">
</SfChart>


// This example demonstrates how to set the title of a Syncfusion Blazor Chart.
<SfChart Title="Chart Title">
</SfChart>


// This example demonstrates how to set the subtitle of a Syncfusion Blazor Chart.
<SfChart Title="Chart Title" SubTitle="Chart SubTitle">
</SfChart>


// This example demonstrates how to set the accessibility description for a Syncfusion Blazor Chart.
<SfChart AccessibilityDescription="Chart Description">
</SfChart>


// This example demonstrates how to set the accessibility role for a Syncfusion Blazor Chart.
<SfChart AccessibilityRole="Chart Description">
</SfChart>


// This example demonstrates how to set the accessibility keyboard navigation focus for a Syncfusion Blazor Chart.
<SfChart Focusable="true">
</SfChart>


// This example demonstrates how to set a background image in a Syncfusion Blazor Chart.
<SfChart BackgroundImage="https://example.com/image.png">
</SfChart>

member.example:

The following example demonstrates how to customize the chart element style using a custom class: 


<SfChart CustomClass="@customClass"> 
    <!-- Other chart configurations -->  
</SfChart> 
<style> 
   .chartcustomclass { 
       width: 100%; 
   } 
</style> 
@code {  
    string customClass = "chartcustomclass"; 
}

